import{_ as t,o as a,c as r,a2 as d}from"./chunks/framework.CFuv5BrO.js";const p=JSON.parse('{"title":"文档地图","description":"Hearth 的文档结构、推荐阅读顺序、维护规则和发布边界。","frontmatter":{"title":"文档地图","description":"Hearth 的文档结构、推荐阅读顺序、维护规则和发布边界。","outline":[2]},"headers":[],"relativePath":"reference/source-map.md","filePath":"reference/source-map.md","lastUpdated":1794450028000}'),h={name:"reference/source-map.md"};function o(l,e,i,s,n,c){return a(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="文档地图" tabindex="-1">文档地图 <a class="header-anchor" href="#文档地图" aria-label="Permalink to &quot;文档地图&quot;">​</a></h1><p class="lead">所有正式文档只在 `docs/` 中维护，仓库和线上站点使用同一份内容。中文是默认路径，英文使用相同结构。找不到某类信息时，可以先从这里确定该读哪一块。</p><h2 id="站点结构" tabindex="-1">站点结构 <a class="header-anchor" href="#站点结构" aria-label="Permalink to &quot;站点结构&quot;">​</a></h2><table tabindex="0"><thead><tr><th>区域</th><th>内容</th><th>入口</th></tr></thead><tbody><tr><td>设计说明</td><td>1 篇总体设计 + 15 篇并列模块设计，按 3 组组织，包含技术选型与存储架构</td><td><a href="/hearth-os/design/">总体设计</a></td></tr><tr><td>交付路线</td><td>六个阶段、24 个小阶段、阶段二至六交付状态和真实验收边界</td><td><a href="/hearth-os/delivery/">交付路线</a></td></tr><tr><td>评测与结果</td><td>Native 30 题基线、最终报告、复现方式与评分边界</td><td><a href="/hearth-os/evaluation/">评测与结果</a></td></tr><tr><td>开发日志</td><td>Day01–Day08 的逐日记录、提交明细与边界</td><td><a href="/hearth-os/log/day-08.html">Day08</a></td></tr><tr><td>附录</td><td>工程、风险、决策、自研边界、术语、清单和维护资料</td><td><a href="/hearth-os/reference/">附录</a></td></tr><tr><td>站点入口</td><td>首页和双语切换</td><td><a href="/hearth-os/">首页</a></td></tr></tbody></table><p>设计说明的十五个模块是入口与交互、任务与持久执行、目标/完成判定与证据、控制面与授权、执行器与路由、原生 Agent Runtime、委派/交接与沙箱、审批与外部副作用、运行环境与安全、存储与上下文架构、个人上下文与注意力、记忆与能力进化、评估与成本、多设备与长期运行与 Agent 参考模式。它们彼此并列，不按代码目录组织。</p><p>第一次了解项目，可以按“为什么做 → 现在有什么 → 还缺什么 → 怎么实现”的顺序阅读：</p><ol><li>从<a href="/hearth-os/design/">总体设计</a>理解产品定位、任务链路、技术选型和模块边界；</li><li>按需要阅读十五个模块，不必按固定顺序；</li><li>看<a href="/hearth-os/delivery/">交付路线</a>确认六个阶段的真实状态：阶段一已验收，阶段二至六已有代码闭环但尚未完成真实验收；</li><li>看<a href="/hearth-os/evaluation/">评测与结果</a>确认 native 30 题的实验 ID、分数和未复测边界；</li><li>准备继续开发时，再看<a href="/hearth-os/reference/engineering.html">工程实施</a>、<a href="/hearth-os/reference/decisions.html">关键决策</a>、<a href="/hearth-os/reference/risks.html">风险与停止条件</a>和<a href="/hearth-os/log/day-08.html">Day08 开发日志</a>。</li></ol><p>只想快速判断项目是否值得继续看，先读总体设计的“产品定位与目标”和交付路线的阶段总览即可。准备实现时，再读工程实施和默认清单。</p><h2 id="维护与发布规则" tabindex="-1">维护与发布规则 <a class="header-anchor" href="#维护与发布规则" aria-label="Permalink to &quot;维护与发布规则&quot;">​</a></h2><ol><li>先改中文页面，确认结论、边界和链接准确，再在同一次提交中更新英文镜像。</li><li>修改设计说明或交付路线后，检查附录、导航、侧栏、首页和语言切换是否仍然对得上。</li><li>设计说明不要引入代码路径、内部类名和实现示例；工程约束留在附录。</li><li>删除旧页面时直接下线，不保留重定向和重复正文；全站搜索旧路径，避免留下死链。</li><li>运行 <code>npm run docs:build</code>，再检查站内链接、移动端宽度、搜索入口和暗色模式。</li><li>不写“应该”“以后会”来掩盖尚未做出的决定；未验证的内容明确标成假设或留空。</li></ol><p>当前文档记录已经实现的代码闭环、已经取得的验收证据，以及仍未验收的边界。阶段二至六有可运行代码和自动测试，但没有用真实账户、真实设备或长期运行冒充完成。开发日志记录当天的工作和提交，不冒充产品发版说明；只有形成可安装版本后，才维护正式版本号和发布说明。</p><p>线上站点应当与仓库的 <code>docs/</code> 构建结果一致。每次发布后检查旧地址是否已经下线、双语页面是否都能访问、侧栏与首页入口是否指向正确结构。</p>',12)])])}const m=t(h,[["render",o]]);export{p as __pageData,m as default};
